import "server-only";

/**
 * Examples of the `metering.site-day` view, so every GUI can be tested
 * against it: days generated by the fixture site samples, built at import
 * the way the loader builds them. A normal day, a day with power cuts and
 * dark time, a site with no battery, and a microgrid with no battery or
 * grid meter registered.
 */
import type { ModelOf } from "@/lib/gui/contract";
import { createFmt } from "@/lib/gui/fmt";
import type { LoadedModel } from "@/lib/gui/surface";
import { addDaysToDateKey } from "@/lib/timezone/day-key";
import { generateSiteSamples, siteScenario, SITE_FIXTURE_SEED, type SiteScenario } from "../fixture/site-samples";
import { computeSiteDay } from "../site-operations";
import type { DeviceConfig } from "@/lib/adapters/types";
import type { SiteSources } from "../types";
import { withSetupLink } from "./site-day";
import { buildNoSiteDevicesModel, buildSiteDayModel } from "./site-day-model";

const ORG = "00000000-0000-4000-8000-0000000000a0";
const MICROGRID = { id: "00000000-0000-4000-8000-0000000000a1", name: "Example site" };
const TIMEZONE = "Africa/Kampala";
const LOCALE = "en-GB";
const RESOLUTION_MINUTES = 5;

/** What the host shows on a model whose Values are synthetic: SYNTHETIC_NOTICE in src/lib/gui/host/server/view.ts, which surface.test.ts compares. */
export const EXAMPLE_SYNTHETIC_NOTICE = {
  tone: "warning",
  text: "Synthetic data: these figures are generated for demonstration, not measured.",
} as const;

const device = (id: string): DeviceConfig => ({ id, edgeOpenemsId: "SYNTHETIC-EDGE-EXAMPLE", componentId: `meter-${id}` });
const FULL: SiteSources = {
  battery: device("battery"),
  gridMeter: device("grid"),
  load: device("load"),
  pv: null,
  houseMeters: [device("house-a"), device("house-b")],
  houseMetersUnreadable: 0,
};
const NO_BATTERY: SiteSources = { ...FULL, battery: null, load: null };

/** The first day from 1 January 2026 that the generator gives `scenario`. */
function dayOf(scenario: SiteScenario): string {
  for (let i = 0; i < 366; i++) {
    const date = addDaysToDateKey("2026-01-01", i);
    if (siteScenario(SITE_FIXTURE_SEED, MICROGRID.id, date) === scenario) return date;
  }
  throw new Error(`no ${scenario} day in 2026`);
}

/** A finished, generated day as the loader returns it. */
function generatedDay(date: string, sources: SiteSources): LoadedModel<"metrics"> {
  const day = computeSiteDay({
    date,
    timezone: TIMEZONE,
    samples: generateSiteSamples({
      microgridId: MICROGRID.id,
      sources,
      startDate: addDaysToDateKey(date, -1),
      endDate: date,
      timezone: TIMEZONE,
      resolutionMinutes: RESOLUTION_MINUTES,
    }),
    sources: {
      battery: sources.battery !== null,
      gridMeter: sources.gridMeter !== null,
      load: sources.load !== null,
      pv: sources.pv !== null,
      houses: sources.houseMeters.length > 0,
      houseMetersUnreadable: 0,
    },
    resolutionMinutes: RESOLUTION_MINUTES,
    nowMs: Date.parse(`${addDaysToDateKey(date, 2)}T00:00:00Z`),
  });
  const today = addDaysToDateKey(date, 1);
  const model = buildSiteDayModel({ ...day, synthetic: true }, { microgrid: MICROGRID, today, locale: LOCALE, fmt: createFmt({ locale: LOCALE }) });
  return withSetupLink(model, MICROGRID.id);
}

/** The models as the loader returns them, before the host fills its fields. */
export const SITE_DAY_LOADED_EXAMPLES: readonly LoadedModel<"metrics">[] = [
  generatedDay(dayOf("clear"), FULL),
  generatedDay(dayOf("long-cut-dark"), FULL),
  generatedDay(dayOf("evening-cut"), NO_BATTERY),
  buildNoSiteDevicesModel({
    microgrid: MICROGRID,
    date: "2026-11-05",
    today: "2026-11-06",
    timezone: TIMEZONE,
    locale: LOCALE,
    fmt: createFmt({ locale: LOCALE }),
  }),
];

/** Each loaded model with the fields the host fills, as a GUI receives it. */
export const SITE_DAY_EXAMPLES: readonly ModelOf<"metrics">[] = SITE_DAY_LOADED_EXAMPLES.map((loaded) => {
  const synthetic = (loaded.ext?.data as { synthetic?: boolean } | undefined)?.synthetic === true;
  return {
    ...loaded,
    type: "view",
    view: "metering.site-day",
    kind: "metrics",
    org: ORG,
    trail: [{ label: MICROGRID.name, href: `/microgrids/${MICROGRID.id}` }],
    actions: [],
    links: loaded.links ?? [],
    attached: [],
    ...(synthetic ? { notice: { ...EXAMPLE_SYNTHETIC_NOTICE } } : {}),
  };
});
